def run(scene, robot):
    tub = scene.get("white tub")
    for pen in scene.of_kind("pen"):
        cur_tub = scene.get(tub.name)
        cur = scene.get(pen.name)
        if cur.x > cur_tub.x + cur_tub.w/2 + 1:
            continue
        x, y = scene.free_spot(near=cur_tub, side="right_of", size=(cur.w, cur.d), clearance=2.0)
        if not robot.can_reach(x, y):
            continue
        robot.pick(cur)
        robot.place_at(x, y)
    robot.home()
